9: 
10: class CurrencyCard extends StatelessWidget {
11:   const CurrencyCard({super.key, required this.model});
12: 
13:   final CurrencyModel model;
14: 
15:   static final _tweenAnimation = Tween<Offset>(begin: Offset(1.0, 0.0), end: Offset.zero);
16: 
17:   @override
18:   Widget build(BuildContext context) {
19:     final PriceChange priceChange = model.asPriceChange;
20:     final ThemeFonts fonts = context.fonts;
21:     final ThemeColors colors = context.colors;
22: 
23:     return GestureDetector(
24:       onTap: () {
25:         Navigator.push(
26:           context,
27:           PageRouteBuilder(
28:             pageBuilder: (BuildContext context, Animation<double> animation, Animation<double> secondaryAnimation) {
29:               return CurrencyDetailPage(title: model.name);
30:             },
31:             transitionsBuilder: (context, animation, secondaryAnimation, child) {
32:               const Cubic curve = Curves.ease;
33: 
34:               final Animatable<Offset> tween = _tweenAnimation.chain(CurveTween(curve: curve));
35:               final Animation<Offset> offsetAnimation = animation.drive(tween);
36: 
37:               return SlideTransition(position: offsetAnimation, child: child);
38:             },
39:           ),
40:         );
41:       },
42:       child: Container(
43:         padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 8),
44:         decoration: BoxDecoration(
45:           color: colors.cardColor,
46:           borderRadius: BorderRadius.circular(12),
47:         ),
48:         child: Row(
49:           children: [
50:             CurrencyIcon(title: model.symbol),
51:             Expanded(
52:               child: Padding(
53:                 padding: const EdgeInsets.symmetric(horizontal: 6),
54:                 child: Text(
55:                   model.name,
56:                   style: fonts.semiBold12,
57:                 ),
58:               ),
59:             ),
60:             Text(
61:               model.value.toStringAsFixed(2),
62:               style: fonts.semiBold12.copyWith(
63:                 color: switch (priceChange) {
64:                   PriceChange.up => colors.greenWrasse,
65:                   PriceChange.down => colors.red,
66:                   PriceChange.stable => colors.stormyGrey,
67:                 },
