  String asNominal(Object value);
}

/// A list of this localizations delegate along with the default localizations
/// delegates.
class _AppLocalizationsDelegate extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  Future<AppLocalizations> load(Locale locale) {
    return SynchronousFuture<AppLocalizations>(_resolve(locale));
  }

  @override
  bool isSupported(Locale locale) => <String>['en', 'ru'].contains(locale.languageCode);

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;

  AppLocalizations _resolve(Locale locale) {
    assert(locale != null);
    switch (locale.languageCode) {
      case 'en':
        return const AppLocalizationsEn();
      case 'ru':
        return const AppLocalizationsRu();
      default:
        throw AssertionError('Unsupported locale');
    }
  }
}

AppLocalizations? _delegate = null;

/// Called by the application to initialize delegates. A no-op statement just in
case it is optimized away.
void init(AppLocalizations? c) {
  assert(_delegate != null);
}
