{"content":"import 'dart:async';

import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _currenciesNotifier;
  late final ValueNotifier<bool> _isLoadingMoreNotifier;

  late final AnimationController _fadeController;

  Future<void>? _loadCurrenciesFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadFreshData(base: 'USD');
  }

  @override
  void dispose() {
    _currenciesNotifier.dispose();
    _isLoadingMoreNotifier.dispose();
    _fadeController.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void reassemble() {
    super.reassemble();
    _loadFreshData(base: 'USD');
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadFreshData({required String base}) async {
    if (mounted) {
      setState(() {
        _currentPage = 0;
        _hasMore = false;
        _currenciesNotifier.value = [];
      });
    }

    final currencyRepository = context.read<CurrencyRepository>();

    try {
      final CurrencyPage page =
          await currencyRepository.fetchRates(CurrencyPageRequest(
        base: base,
        page: 0,
      ));

      if (mounted) {
        setState(() {
          _allCurrencies = List.unmodifiable(page.items);
          _currenciesNotifier.value = List.unmodifiable(page.items);
          _hasMore = page.hasMore;
          _currentPage = 0;
        });

        _fadeController.forward();

        await currencyRepository.saveCurrencyList(_allCurrencies);
      }
    } catch (_) {
      if (mounted) {
        setState(() {});
      }
    }
  }

  void _filterCurrencies(String query, List<CurrencyModel> allItems) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = allItems.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    });

    setState(() {
      _currenciesNotifier.value = List.unmodifiable(result.toList(growable: false));
    });
  }

  Future<void> _loadMore() async {
    if (_isLoadingMoreNotifier.value) return;

    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _isLoadingMoreNotifier.value = true;
    });

    try {
      final nextPage = _currentPage + 1;
      final CurrencyPage page = await currencyRepository.fetchRates(CurrencyPageRequest(
        base: 'USD',
        page: nextPage,
      ));

      if (mounted) {
        setState(() {
          _allCurrencies = List.unmodifiable([..._allCurrencies, ...page.items]);
          _currenciesNotifier.value = List.unmodifiable(_allCurrencies);
          _hasMore = page.hasMore;
          _currentPage = nextPage;
        });
      }
    } catch (_) {}

    if (mounted) {
      setState(() {
        _isLoadingMoreNotifier.value = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _loadCurrenciesFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          final List<CurrencyModel>? data = _currenciesNotifier.value;

          if (data == null || data.isEmpty && !snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(
                    onChanged: (String query) => _filterCurrencies(query, _allCurrencies),
                  ),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _currenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> dataWidget, _) {
                      return ListView.builder(
                        itemCount: dataWidget.length + (_hasMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index >= dataWidget.length) {
                            // Показываем индикатор загрузки при подгрузке
                            return _isLoadingMoreNotifier.value
                                ? const Padding(
                                    padding: EdgeInsets.all(24.0),
                                    child: Center(child: CircularProgressIndicator()),
                                  )
                                : Container();
                          }

                          final CurrencyModel currency = dataWidget[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0
                                ? const EdgeInsets.only(top: 20)
                                : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 80),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
      floatingActionButton: !_hasMore
          ? null
          : FloatingActionButton.extended(
              onPressed: _isLoadingMoreNotifier.value ? null : _loadMore,
              label: Text(context.loc.showMore),
              icon: const Icon(Icons.add_circle_outline),
            ),
    );
  }
}
