import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('CurrencyListPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(
            items: [
              CurrencyModel(
                id: '1',
                nominal: 1,
                name: 'Доллар США',
                symbol: 'USD',
                value: 78.4181,
                previousValue: 78.5,
              ),
              CurrencyModel(
                id: '2',
                nominal: 1,
                name: 'Евро',
                symbol: 'EUR',
                value: 92.7440,
                previousValue: 92.2,
              ),
            ],
            page: 0,
            hasMore: false,
          ));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      // Ждём загрузку данных (CircularProgressIndicator заменяется на список)
      await tester.pumpAndSettle();

      expect(find.text('USD'), findsOneWidget);
      expect(find.text('EUR'), findsOneWidget);
      expect(find.text('JPY'), findsNothing);
      expect(find.byType(CurrencyCard), findsNWidgets(2));
    });

    testWidgets('should hide FAB when hasMore is false', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.byType(FloatingActionButton), findsNothing);
    });

    testWidgets('should display FAB when hasMore is true', (WidgetTester tester) async {
      // Mock с hasMore: true
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(
            items: [
              CurrencyModel(
                id: '1',
                nominal: 1,
                name: 'Доллар США',
                symbol: 'USD',
                value: 78.4181,
                previousValue: 78.5,
              ),
            ],
            page: 0,
            hasMore: true,
          ));

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.byType(FloatingActionButton), findsOneWidget);
    });

    testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should call fetchRates with base USD on initial load', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((invocation) async {
        final CurrencyPageRequest request = invocation.positionalArguments[0] as CurrencyPageRequest;
        expect(request.base, 'USD');
        return const CurrencyPage(items: [], page: 0, hasMore: false);
      });

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      verify(mockCurrencyRepository.fetchRates(any)).called(1);
    });

    testWidgets('should call fetchRates with base USD on reassemble', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((invocation) async {
        final CurrencyPageRequest request = invocation.positionalArguments[0] as CurrencyPageRequest;
        expect(request.base, 'USD');
        return const CurrencyPage(items: [], page: 0, hasMore: false);
      });

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      // Первый вызов при initState
      await tester.pumpAndSettle();
      verify(mockCurrencyRepository.fetchRates(any)).called(1);

      // Симуляция reassemble (возврат на экран)
      tester.binding.reassembleApplication(tester.platformDispatcher.orderedViews.first.debugName, const DebugReport());
      await tester.pumpAndSettle();

      // Второй вызов после reassemble
      verify(mockCurrencyRepository.fetchRates(any)).called(2);
    });

    testWidgets('should show CircularProgressIndicator while loading initial data', (WidgetTester tester) async {
      late final Future<CurrencyPage> future;
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) => future);

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      // В процессе загрузки показывается CircularProgressIndicator
      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      // Отдаём данные
      final Completer<CurrencyPage> completer = Completer();
      future = completer.future;
      await tester.pump();

      completer.complete(const CurrencyPage(items: [], page: 0, hasMore: false));
      await tester.pumpAndSettle();

      // После загрузки CircularProgressIndicator исчезает (или остаётся при загрузке)
      expect(find.byType(CurrencyListPage), findsOneWidget);
    });
  });
}

